import { useEffect, useMemo, useState } from "react";
import { useTranslation } from "react-i18next";

export interface LicensePackage {
  name: string;
  version: string;
  ecosystem: "npm" | "cargo";
  /** The package's own copyright lines, or its authors when it states none. */
  copyright: string[];
}

export interface LicenseGroupData {
  id: string;
  title: string;
  kind: "license" | "notice";
  text: string;
  packages: LicensePackage[];
}

export interface ThirdPartyLicenseData {
  packageCount: number;
  groups: LicenseGroupData[];
}

/**
 * Generated by `npm run notice:generate`. Imported lazily so the (large) text is
 * only loaded when the Licenses tab is opened.
 */
function loadBundledLicenses(): Promise<ThirdPartyLicenseData> {
  return import("../../assets/licenses/third-party.json").then(
    (module) => module.default as ThirdPartyLicenseData,
  );
}

type LoadState =
  | { status: "loading" }
  | { status: "ready"; data: ThirdPartyLicenseData }
  | { status: "error" };

function LicenseGroup({
  group,
  query,
}: {
  group: LicenseGroupData;
  query: string;
}) {
  const { t } = useTranslation("about");
  const [open, setOpen] = useState(false);

  const packages = useMemo(
    () =>
      query === ""
        ? group.packages
        : group.packages.filter((pkg) =>
            `${pkg.name} ${pkg.version}`.toLowerCase().includes(query),
          ),
    [group.packages, query],
  );

  if (query !== "" && packages.length === 0) return null;

  // While searching, every group with a match is expanded so results are visible.
  const expanded = open || query !== "";

  return (
    <details
      className="about-licenses-oss__group"
      open={expanded}
      onToggle={(event) => {
        if (query === "") setOpen(event.currentTarget.open);
      }}
    >
      <summary className="about-licenses-oss__summary">
        <span className="about-licenses-oss__group-title">{group.title}</span>
        <span className="about-licenses-oss__count">
          {t("licenses.openSource.usedBy", { count: packages.length })}
        </span>
      </summary>
      {expanded ? (
        <div className="about-licenses-oss__detail">
          <ul className="about-licenses-oss__packages">
            {packages.map((pkg) => (
              <li
                key={`${pkg.ecosystem}:${pkg.name}@${pkg.version}`}
                className="about-licenses-oss__package"
              >
                <span className="about-licenses-oss__package-name">
                  {pkg.name} {pkg.version}
                </span>
                {pkg.copyright.map((line) => (
                  <span key={line} className="about-licenses-oss__copyright">
                    {line}
                  </span>
                ))}
              </li>
            ))}
          </ul>
          <pre className="about-licenses-doc__body">{group.text}</pre>
        </div>
      ) : null}
    </details>
  );
}

export function ThirdPartyLicenses({
  loadData = loadBundledLicenses,
}: {
  loadData?: () => Promise<ThirdPartyLicenseData>;
}) {
  const { t } = useTranslation("about");
  const [state, setState] = useState<LoadState>({ status: "loading" });
  const [search, setSearch] = useState("");

  useEffect(() => {
    let cancelled = false;
    loadData().then(
      (data) => {
        if (!cancelled) setState({ status: "ready", data });
      },
      () => {
        if (!cancelled) setState({ status: "error" });
      },
    );
    return () => {
      cancelled = true;
    };
  }, [loadData]);

  const query = search.trim().toLowerCase();

  const anyMatch = useMemo(() => {
    if (state.status !== "ready" || query === "") return true;
    return state.data.groups.some((group) =>
      group.packages.some((pkg) =>
        `${pkg.name} ${pkg.version}`.toLowerCase().includes(query),
      ),
    );
  }, [state, query]);

  return (
    <section
      className="about-licenses-oss"
      aria-labelledby="about-license-open-source"
    >
      <h3 id="about-license-open-source" className="about-licenses-doc__title">
        {t("licenses.openSource.title")}
      </h3>
      <p className="about-licenses-oss__intro">
        {t("licenses.openSource.intro")}
      </p>

      {state.status === "loading" ? (
        <p role="status" className="about-licenses-oss__status">
          {t("licenses.openSource.loading")}
        </p>
      ) : null}
      {state.status === "error" ? (
        <p role="alert" className="about-licenses-oss__status">
          {t("licenses.openSource.loadFailed")}
        </p>
      ) : null}

      {state.status === "ready" ? (
        <>
          <div className="about-licenses-oss__toolbar">
            <input
              type="search"
              className="about-licenses-oss__search"
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              placeholder={t("licenses.openSource.searchPlaceholder")}
              aria-label={t("licenses.openSource.searchLabel")}
            />
            <span className="about-licenses-oss__total">
              {t("licenses.openSource.summary", {
                count: state.data.packageCount,
              })}
            </span>
          </div>
          {anyMatch ? (
            state.data.groups.map((group) => (
              <LicenseGroup key={group.id} group={group} query={query} />
            ))
          ) : (
            <p className="about-licenses-oss__status">
              {t("licenses.openSource.noMatches", { query: search.trim() })}
            </p>
          )}
        </>
      ) : null}
    </section>
  );
}
